import{_ as t,o as e,c as o,ag as l}from"./chunks/framework.CAXxHpAX.js";const q=JSON.parse('{"title":"无明","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-无明.md","filePath":"50-概念资料/dict-无明.md","lastUpdated":1778031108000}'),r={name:"50-概念资料/dict-无明.md"};function i(d,a,u,h,n,c){return e(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="无明" tabindex="-1">无明 <a class="header-anchor" href="#无明" aria-label="Permalink to &quot;无明&quot;">​</a></h1><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>无明（梵语 Avidya）在佛教中指对实相的无知——不了解万法皆空的道理，因无知而生执着，因执着而受苦。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;无明就是不了解万法皆空——不了解一切现象都是因缘和合而生、不永恒的。&quot;</p></blockquote><blockquote><p>&quot;过去心不可得，现在心不可得，未来心不可得——你不懂这个道理，就是无明。懂了，无明就破了。&quot;</p></blockquote><h2 id="了空居士对无明的特殊诠释" tabindex="-1">了空居士对无明的特殊诠释 <a class="header-anchor" href="#了空居士对无明的特殊诠释" aria-label="Permalink to &quot;了空居士对无明的特殊诠释&quot;">​</a></h2><p>了空居士不讲复杂的唯识学名相，他直接把无明解释为<strong>对&quot;缘起性空&quot;的无知</strong>。破无明的方法也很直接——<strong>明白了诸法空相，无明就破了</strong>，不需要经过漫长的次第。</p><blockquote><p>&quot;照见五蕴皆空，度一切苦厄。&quot;</p></blockquote><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-清净心">清净心</a> — 破无明后的心状态</li><li><a href="/50-概念资料/dict-我执">我执</a> — 无明的表现</li><li><a href="/50-概念资料/dict-烦恼">烦恼</a> — 无明的结果</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/model-天人合一">天人合一</a> — 缘起性空的宇宙观</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>每天提醒自己&quot;一切都在变化&quot;</li><li>当烦恼升起时，追问&quot;这个烦恼的根源是什么？&quot;</li><li>学习经典（金刚经、心经）从道理上明白</li></ul>',15)])])}const _=t(r,[["render",i]]);export{q as __pageData,_ as default};
